-- =========================================================================
-- D24 — les 288 textes intégraux restreints d'Anarchief.org, en EPUB, lisibles
-- par les membres des bibliothèques détentrices
-- =========================================================================
-- Date     : 2026-10-23
-- Chantier : documents numériques — EPUB des textes intégraux d'Anarchief.org
-- Auteur   : Claude (assistant·e), pour la coordination
-- Ref      : backlog D24 ; 20261023154059_d24_les_206_epub_ouverts_d_anarchief
--            (les ouverts, même forme) ; 20261023152846 (le seau restreint)
--
-- POURQUOI
--   Décision de Xavier du 23/10/2026 (D24, « on prend les 291 restreints ») :
--   les textes dont le lot n'a pas de lettre A ou B dans la feuille des lots
--   de textes (lettre C : 80 ; lot sans lettre : 208) se lisent sous compte,
--   comme les PDF restreints.
--
-- CE QUI EST FAIT HORS DE CE PAQUET (23/10/2026)
--   291 textes : 288 EPUB fabriqués (pandoc ; trois pages sans texte une fois
--   le wikitexte nettoyé), versés dans anarbib-epub-restricted depuis la
--   session (aal2) de l'administration du réseau, empreinte comparée au
--   manifeste avant l'envoi : 288 objets, 12 247 794 octets.
--
-- CE QUE FAIT LE PAQUET
--   288 ressources « epub » : conta_ativa, sob_direitos, validées (même source,
--   NUMDIF-6), JAMAIS principales — le bouton « Lire » ne propose que du public ;
--   elles se montrent dans « Autres formats » (api.book_documents_v1),
--   « réservé » pour qui ne peut pas les lire, avec le lien pour les membres
--   d'une bibliothèque détentrice. Justification : le lot de textes et sa
--   lettre. Rejouable.
--
-- CHECKLIST DOCTRINE
--   [x] Donnée gardée : 288 en production (chaque objet présent), 0 au banc
--   [x] Aucun objet créé, aucun droit touché
-- =========================================================================

BEGIN;

DO $d24r$
DECLARE
  c_anarchief constant uuid := '1bb157fd-4d1f-415b-9e5d-490f4f8d0895';
  c_seau      constant text := 'anarbib-epub-restricted';
  v_n int; v_manque text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.libraries WHERE id = c_anarchief) THEN
    RAISE NOTICE 'D24 : bibliothèque Anarchief.org absente (banc), rien à faire.';
    RETURN;
  END IF;

  CREATE TEMP TABLE d24_epub_r (book_id bigint, page int, chemin text, sha256 text, taille bigint, page_url text, justif text) ON COMMIT DROP;

  SELECT string_agg(e.page::text, ',') INTO v_manque FROM d24_epub_r e
   WHERE NOT private.fn_objet_stocke_existe(c_seau, e.chemin)
      OR NOT EXISTS (SELECT 1 FROM public.book_holdings h WHERE h.book_id = e.book_id AND h.library_id = c_anarchief)
      OR NOT EXISTS (SELECT 1 FROM public.books b WHERE b.id = e.book_id AND b.bib_ref = 'ANARCHIEF-' || e.page);
  IF v_manque IS NOT NULL THEN
    RAISE EXCEPTION 'D24 : objet absent, notice non détenue ou cote différente pour les pages %', v_manque;
  END IF;

    book_id, resource_type, usage_type, access_scope, status, is_active, is_primary, mime_type,
    label, notes, metadata, source_url, source_page_url, source_name, attribution_text,
    rights_status, rights_justification, bibliographic_match_validated,
    storage_bucket, storage_path, language_code, activated_at)
  SELECT e.book_id, 'epub', 'leitura_online', 'conta_ativa', 'active', true, false, 'application/epub+zip',
         left(b.titulo || ' (texto integral, EPUB)', 300),
         'Texto integral transcrito no wiki da fonte (Anarchief.org, página ' || e.page || '), convertido em EPUB pela AnarBib em 23/10/2026. '
           || 'Leitura reservada aos membros das bibliotecas detentoras ; arquivo e ficha da mesma fonte (NUMDIF-6) ; validado pela administração da rede (D24).',
         jsonb_build_object('sha256', e.sha256, 'file_size_bytes', e.taille, 'source_identifier', 'anarchief:' || e.page,
                            'source_file', 'anarchief-' || e.page || '.epub', 'deposited_via', 'D24 : versement depuis la session de l''administration du réseau',
                            'conversion', 'pandoc mediawiki -> epub3 (epub-anarchief.py)'),
         e.page_url, e.page_url, 'Anarchief.org',
         'Fonte: Anarchief.org (página ' || e.page || ')',
         'sob_direitos', e.justif, true,
         c_seau, e.chemin,
         CASE WHEN b.idioma ~ '^[a-z]{2,3}(-[A-Z]{2})?$' THEN b.idioma END,
         now()
    FROM d24_epub_r e JOIN public.books b ON b.id = e.book_id
   WHERE NOT EXISTS (SELECT 1 FROM public.book_digital_resources x WHERE x.storage_bucket = c_seau AND x.storage_path = e.chemin);

  SELECT count(*) INTO v_n
    FROM public.book_digital_resources r JOIN d24_epub_r e ON r.storage_bucket = c_seau AND r.storage_path = e.chemin
   WHERE r.resource_type = 'epub' AND r.is_active AND r.access_scope = 'conta_ativa' AND NOT r.is_primary;
  IF v_n <> 288 THEN
    RAISE EXCEPTION 'D24 : % ressources EPUB restreintes, 288 attendues', v_n;
  END IF;
  RAISE NOTICE 'D24 : 288 ressources EPUB restreintes.';
END
$d24r$;

COMMIT;
